def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    supply = day_context['supply']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water >= 1:
            return min(budget, 50.0)
        return min(budget, 24.0)

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    n_players = 1 + len(alive)
    approx_units = float(supply) / float(WATER_REQ)
    scarcity = approx_units < n_players

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if hp <= 1:
        bid = 68.0
    elif hp <= 2 or no_water >= 2:
        bid = 62.0
    elif no_water >= 1:
        bid = 52.0
    else:
        if scarcity:
            if highest_prev >= 60:
                bid = 41.0
            elif highest_prev >= 45:
                bid = highest_prev + 2.0
            elif highest_prev > 0:
                bid = max(36.0, avg_prev + 3.0)
            else:
                bid = 37.0
        else:
            if highest_prev >= 60:
                bid = 22.0
            elif highest_prev >= 45:
                bid = 28.0
            elif highest_prev > 0:
                bid = min(34.0, avg_prev + 1.5)
            else:
                bid = 26.0

    if urgent_opp >= max(1, len(alive) // 2):
        bid += 4.0
    if rich_opp >= max(1, len(alive) // 2) and scarcity:
        bid += 3.0

    if budget < bid:
        if hp <= 2 or no_water >= 1:
            return max(0.0, budget)
        return max(0.0, min(budget, bid))

    return max(0.0, min(float(budget), float(bid)))

