def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Base bid depends on remaining HP and current supply
    # If supply is tight (near MIN_SUPPLY), we bid more to avoid being starved.
    supply_band = (supply - 15.0) / (25.0 - 15.0) if 25.0 != 15.0 else 0.5
    tightness = 1.0 - max(0.0, min(1.0, supply_band))

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Aggression detection: if someone bid close to their salary, expect continued pressure.
    pressure_threshold = DAILY_SALARY * 0.85

    if highest_prev_bid >= pressure_threshold:
        # Compete but do not chase fully; preserve budget if our HP is low.
        if hp > 3.0:
            target = DAILY_SALARY * (0.25 + 0.15 * tightness)
        else:
            target = DAILY_SALARY * (0.65 + 0.10 * tightness)
        bid = min(budget, target)
        # If we have enough budget, slightly overbid relative to yesterday's highest.
        if highest_prev_bid > 0.0:
            bid = max(bid, min(budget, highest_prev_bid * 0.95))
        return bid
    else:
        # Low bids yesterday: secure water with a moderate bid.
        # Use a small bump if we are low on HP or supply is tight.
        hp_factor = 0.15 if hp <= 2.0 else (0.05 if hp <= 3.0 else 0.0)
        target = DAILY_SALARY * (0.45 + 0.25 * tightness + hp_factor)
        bid = min(budget, target)
        # If we can, nudge above yesterday's highest to win the allocation.
        if highest_prev_bid > 0.0:
            bid = max(bid, min(budget, highest_prev_bid + 1.5))
        return bid
